pub struct Texture { pub width: u32, pub height: u32, pixels: Vec<u32> }
impl Texture { pub fn new(width: u32, height: u32) -> Result<Self, &'static str> { let count = (width as usize).checked_mul(height as usize).ok_or("texture size overflow")?; if count == 0 { return Err("texture dimensions are zero"); } Ok(Self { width, height, pixels: vec![0; count] }) } pub fn set(&mut self, x: u32, y: u32, color: u32) -> Result<(), &'static str> { if x >= self.width || y >= self.height { return Err("texture coordinate out of bounds"); } self.pixels[(y * self.width + x) as usize] = color; Ok(()) } }
